#nullable enable
using Alba;
using Drafting.Contracts;
using Drafting.Slices.Drafting;
using Drafting.Views;
using Marten;
using Shouldly;
using Xunit;

namespace Drafting.IntegrationTests.Slices.Drafting;

/// <summary>
/// The CREATE slice. It exists so revise-subject has a stream to act on — the aggregate handler workflow is
/// about changing something that already exists, and something has to have made it.
/// </summary>
public sealed class DraftEmailTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private async Task<IScenarioResult> Post(Guid emailId, string to) =>
        (await WhenPosting(x =>
        {
            x.Post.Json(new DraftEmail(emailId, to, "Original subject", "Body"))
                .ToUrl(DraftEmailEndpoint.Route);
            x.IgnoreStatusCode();
        })).Item2;

    // a composed email becomes a draft
    //   GIVEN (nothing)
    //   WHEN  DraftEmail
    //   THEN  EmailDrafted
    [Fact]
    public async Task AComposedEmailBecomesADraft()
    {
        var emailId = Guid.NewGuid();

        (await Post(emailId, "someone@example.com")).Context.Response.StatusCode.ShouldBe(204);

        var drafted = (await EventsFor(emailId)).OfType<EmailDrafted>().ShouldHaveSingleItem();
        drafted.EmailId.ShouldBe(emailId);
        drafted.Subject.ShouldBe("Original subject");

        // The stream key IS the emailId — no prefix — which is the whole reason [WriteAggregate] can find
        // this stream from a route argument in the next slice.
        await using var session = Store.QuerySession();
        (await session.LoadAsync<MyDrafts>(emailId))!.Subject.ShouldBe("Original subject");
    }

    // a draft with no recipient is refused
    //   GIVEN (nothing)
    //   WHEN  DraftEmail
    //   THEN  error: RecipientRequired
    [Fact]
    public async Task ADraftWithNoRecipientIsRefused()
    {
        var emailId = Guid.NewGuid();

        var result = await Post(emailId, "");

        result.Context.Response.StatusCode.ShouldBe(400);
        (await result.ReadAsTextAsync()).ShouldContain("RecipientRequired");

        // Refused before any stream was read, so nothing exists at all — the other side of the boundary.
        (await EventsFor(emailId)).ShouldBeEmpty();
    }
}
